pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(depositAmount > 0 && depositAmount <= type(uint128).max);
        vm.assume(withdrawAmount > 0 && withdrawAmount <= type(uint128).max);

        vm.deal(actor, depositAmount);
        vm.prank(actor);
        c.deposit{value: depositAmount}();

        // Deploy a reverter that always fails on receiving ETH
        Reverter reverter = new Reverter();
        // Deposit some ETH to the reverter so it has credit
        vm.deal(address(this), withdrawAmount);
        c.deposit{value: withdrawAmount}();

        // Calculate expected balance invariant before withdraw
        uint256 balanceBefore = address(c).balance;

        // The reverter calls withdrawAll - its receive will revert
        vm.prank(address(reverter));
        try c.withdrawAll() { } catch { }

        // After: balance must not decrease if the call failed (credit is untouched on revert in correct version)
        // The invariant: balance + sum(credit) == balanceBefore + sum(credit)Before, simplified:
        // Since no credit changed on revert in correct, balance must equal balanceBefore.
        // The bug reduces balance and zeroes credit, causing balance < balanceBefore.
        uint256 balanceAfter = address(c).balance;
        assertTrue(balanceAfter <= balanceBefore);
    }
}

