pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Reverter reverter;

    function setUp() public {
        c = new C();
        reverter = new Reverter();
    }

    function testFuzz_property(uint256 amount, uint256 extraAmount) public {
        vm.assume(amount > 0);
        vm.assume(extraAmount > 0);

        // Setup: two separate depositors to ensure balance > credit for the reverter
        address user1 = address(reverter);
        address user2 = address(0x1234);

        vm.deal(user1, amount);
        vm.deal(user2, extraAmount);

        vm.prank(user1);
        c.deposit{value: amount}();
        vm.prank(user2);
        c.deposit{value: extraAmount}();

        uint256 balanceBefore = address(c).balance;
        uint256 creditBefore = c.credit(user1);

        // withdrawAll from the reverter will fail on the low-level call
        vm.prank(user1);
        bool success;
        try c.withdrawAll() { success = true; } catch { success = false; }

        uint256 balanceAfter = address(c).balance;
        uint256 creditAfter = c.credit(user1);

        if (!success) {
            // The call failed, so the credit MUST be restored and balance unchanged
            assertTrue(creditAfter == creditBefore && balanceAfter == balanceBefore);
        } else {
            // If it succeeds (which should not happen for the reverter),
            // just accept any state as valid reference.
            assertTrue(true);
        }
    }
}

