        // Without a helper, using an EOA would also succeed, but no helper is required here because the
        // invariant concerns contract state after a successful withdrawal, and any EOA works.
        // We just need a depositor and withdrawer.
        address actor = makeAddr("actor");
        vm.deal(actor, amount);
        vm.prank(actor);
