        vm.prank(actor1);
        c.deposit{value: depositAmount}();

        // Record balance after first deposit.
        uint256 balanceAfterDeposit1 = address(c).balance;

        vm.prank(actor1);
        c.withdrawAll();

        // Actor1 should have zero credit after successful withdrawal, so repeated withdrawAll should yield nothing.
        // Meanwhile, actor2 deposits independently.
        vm.deal(actor2, extraAmount);
        vm.prank(actor2);
        c.deposit{value: extraAmount}();

        uint256 balanceAfterDeposit2 = address(c).balance;

        // Actor1 tries to withdraw again — correct contract gets 0, buggy gets depositAmount again.
        vm.prank(actor1);
        c.withdrawAll();

        uint256 finalBalance = address(c).balance;

        // Invariant: final balance must equal balanceAfterDeposit2 (actor1's credit was already drained).
        // The bug will make finalBalance lower because actor1 withdraws depositAmount again.
        assertTrue(finalBalance == balanceAfterDeposit2);
    }
}

