pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 depositAmount, uint8 withdrawCount) public {
        // Restrict deposit to a reasonable range (avoid overflow, keep non-zero after bounding)
        depositAmount = bound(depositAmount, 1, 100 ether);
        withdrawCount = withdrawCount % 5; // 0–4 withdrawals

        address actor = address(0x10000);
        vm.deal(actor, depositAmount);

        // Deposit once
        vm.prank(actor);
        c.deposit{value: depositAmount}();

        // Perform withdrawCount withdrawals (each attempting via withdrawAll)
        for (uint256 i = 0; i < withdrawCount; i++) {
            vm.prank(actor);
            try c.withdrawAll() { } catch { }
        }

        // After all actions, the contract balance must be at least the sum of all credits.
        // We compute the sum of credits by querying a public getter for the mapping.
        // credit is private, but Solidity auto-generates a getter for `public` variables;
        // credit is not public. Thus we can't directly read credit[actor] from outside.
        // However, we can observe that if contract balance falls below the total credit
        // stored internally, the invariant is broken. To capture this without a public
        // credit getter, we reason differently: after any sequence of legitimate operations,
        // the contract's balance should never be less than the amount the actor can still
        // successfully withdraw. If the actor can withdraw more than the current balance,
        // the invariant is broken. A public view returning withdrawable amount may not exist.
        // Instead, we observe that after a sequence of deposit/withdrawAll calls,
        // a subsequent withdrawAll must not reduce the contract's ETH balance below zero.
        // The bug allows repeated withdrawals draining more than deposited, eventually
        // causing the contract to have insufficient balance for a withdrawAll attempt,
        // which would revert due to a failed low-level call. The reference never reverts
        // a withdrawAll after a single deposit and repeated calls; it returns silently
        // on subsequent calls (credit == 0, early exit). The mutant eventually causes
        // a revert when the contract's balance is exhausted.
        // Thus, property: after the sequence, calling withdrawAll again MUST NOT revert.
        uint256 balanceBefore = address(c).balance;
        bool success;
        vm.prank(actor);
        try c.withdrawAll() { success = true; } catch { success = false; }
        assertTrue(success);
    }
}

