pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount) public {
        // Use a low-level call helper that fails when receiving Ether,
        // so that the withdrawAll's external call always reverts.
        // This makes the mutation's effect purely on internal state.
        Reverter reverter = new Reverter();
        address actor = address(reverter);
        vm.assume(depositAmount > 0);
        vm.deal(actor, depositAmount);
        vm.startPrank(actor);
        c.deposit{value: depositAmount}();
        try c.withdrawAll() { } catch { }
        vm.stopPrank();

        // Invariant: contract balance equals sum of all credits.
        // Since only the actor deposited, total credits are still credit[actor].
        uint256 totalCredits = c.credit(actor);
        assertEq(address(c).balance, totalCredits, "Contract balance must equal sum of all remaining credits");
    }
}

contract Reverter {
    function credit(address) external view returns (uint256) { return 0; }
    fallback() external payable { revert(); }
}

