pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount) public {
        // Bound amount to a reasonable range to avoid overflow and ensure enough ETH for calls
        amount = bound(amount, 1, 100 ether);

        // Deploy a reentrant helper that will re-enter withdrawAll on receive
        ReentrantHelper helper = new ReentrantHelper(c);
        address attacker = address(helper);

        // Fund the attacker
        vm.deal(attacker, amount);

        // Attacker deposits to establish credit
        vm.startPrank(attacker);
        c.deposit{value: amount}();
        vm.stopPrank();

        // Record ETH balance and credit before withdrawal
        uint balanceBefore = address(c).balance;
        uint creditBefore = c.credit(attacker);

        // Attacker calls withdrawAll; helper will attempt a reentrant call in its receive
        vm.startPrank(attacker);
        c.withdrawAll();
        vm.stopPrank();

        // After one top-level withdrawAll, the caller's credit must be zero
        uint creditAfter = c.credit(attacker);
        // The ETH balance must have decreased by exactly creditBefore (no more)
        uint balanceAfter = address(c).balance;
        assertTrue(creditAfter == 0 && balanceBefore - balanceAfter == creditBefore);
    }
}

contract ReentrantHelper {
    C target;
    constructor(C _target) { target = _target; }
    receive() external payable {
        // Re-enter withdrawAll only once to trigger the bug if possible
        if (address(target).balance >= 1 wei) {
            target.withdrawAll();
        }
    }
}

