pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 initialCredit, uint256 reentrantAmount) public {
        // Bound amounts to avoid overflow and ensure reentrantAmount is at most initialCredit
        initialCredit = bound(initialCredit, 1, 1000 ether);
        reentrantAmount = bound(reentrantAmount, 1, initialCredit);

        // Deploy a reentrant attacker that will attempt to withdraw reentrantAmount during its receive hook
        Attacker attacker = new Attacker(c, reentrantAmount);
        address attackerAddr = address(attacker);

        // Fund the contract with initialCredit via deposit from attacker
        vm.deal(attackerAddr, initialCredit);
        vm.prank(attackerAddr);
        c.deposit{value: initialCredit}();

        uint256 contractBalanceBefore = address(c).balance;

        // Attacker initiates withdrawAll, which will trigger reentrancy
        vm.prank(attackerAddr);
        attacker.attack();

        uint256 contractBalanceAfter = address(c).balance;
        uint256 balanceDecrease = contractBalanceBefore - contractBalanceAfter;

        // Reference invariant: ETH balance decrease must not exceed the single initial credit assigned to the caller.
        // The bug allows reentrancy that causes a larger decrease.
        assertTrue(balanceDecrease <= initialCredit);
    }
}

contract Attacker {
    C public target;
    uint256 public reentrantAmount;
    bool private attacking;

    constructor(C _target, uint256 _reentrantAmount) {
        target = _target;
        reentrantAmount = _reentrantAmount;
    }

    function attack() external payable {
        attacking = true;
        target.withdrawAll();
        attacking = false;
    }

    receive() external payable {
        if (attacking && reentrantAmount > 0 && address(target).balance >= reentrantAmount) {
            // Reenter withdrawAll to exploit the zero-credit-before-balance-decrease bug
            target.withdrawAll();
        }
    }
}

